-- Maths V2 performance coach: repair, readiness, timed calculation, approach and SSC sprint.

insert into maths.repair_queue(user_id,scope_type,scope_id,question_id,reason,priority,status,priority_score,source_evidence_id,due_at,next_confirmation_at,metadata,created_at)
select e.user_id,case when qf.family_id is not null then 'family' when qc.concept_id is not null then 'concept' else 'question' end,coalesce(qf.family_id,qc.concept_id,e.question_id),e.question_id,case when e.slow_correct then 'TIME' else null end,case when coalesce(fs.persistent_weak,false) then 'P0' else 'P1' end,'open',case when coalesce(fs.persistent_weak,false) then 120 else 75 end+case when e.slow_correct then 8 else 15 end,e.evidence_id,case when coalesce(fs.persistent_weak,false) then now() else greatest(now(),e.created_at+interval '18 hours') end,greatest(now()+interval '20 hours',e.created_at+interval '20 hours'),jsonb_build_object('backfilled',true,'diagnosisNeeded',not e.slow_correct,'timingClass',e.timing_class),e.created_at
from(select distinct on(user_id,scope_key)* from(select e.*,coalesce(qf.family_id,qc.concept_id,e.question_id)scope_key from maths.performance_evidence e left join maths.question_families qf on qf.question_id=e.question_id and qf.active left join lateral(select concept_id from maths.question_concepts x where x.question_id=e.question_id and x.active order by confidence desc limit 1)qc on true where e.created_at>=now()-interval '45 days' and(e.correctness='wrong' or e.slow_correct)and not exists(select 1 from maths.performance_evidence g left join maths.question_families gf on gf.question_id=g.question_id and gf.active left join lateral(select concept_id from maths.question_concepts gx where gx.question_id=g.question_id and gx.active order by confidence desc limit 1)gc on true where g.user_id=e.user_id and g.correctness='correct' and not g.slow_correct and g.created_at>e.created_at and coalesce(gf.family_id,gc.concept_id,g.question_id)=coalesce(qf.family_id,qc.concept_id,e.question_id)))z order by user_id,scope_key,created_at desc)e
left join maths.question_families qf on qf.question_id=e.question_id and qf.active left join lateral(select concept_id from maths.question_concepts x where x.question_id=e.question_id and x.active order by confidence desc limit 1)qc on true left join maths.family_state fs on fs.user_id=e.user_id and fs.family_id=qf.family_id
where not exists(select 1 from maths.repair_queue rq where rq.user_id=e.user_id and rq.scope_type=case when qf.family_id is not null then 'family' when qc.concept_id is not null then 'concept' else 'question' end and rq.scope_id=coalesce(qf.family_id,qc.concept_id,e.question_id) and rq.status in('open','in_progress','waiting_confirmation'));

create or replace function maths._repair_candidate_ids(p_uid uuid,p_count integer default 5,p_reason text default null)returns text[] language sql stable security definer set search_path='pg_catalog','public','maths' as $$
with queue as(select rq.* from maths.repair_queue rq where rq.user_id=p_uid and rq.status in('open','waiting_confirmation')and(rq.due_at<=now() or rq.priority='P0')and(p_reason is null or rq.reason=upper(p_reason))order by case rq.priority when 'P0' then 1 when 'P1' then 2 when 'P2' then 3 else 4 end,rq.priority_score desc,rq.due_at limit 20),candidates as(
select q.repair_id,q.priority,q.priority_score,q.question_id source_question,r.question_id,row_number()over(partition by q.repair_id order by(r.question_id<>coalesce(q.question_id,''))desc,(coalesce(st.mastered,false)=false)desc,coalesce(st.attempts,0),abs(hashtext(r.question_id||q.repair_id::text)))family_rank from queue q join maths.question_families f on q.scope_type='family' and f.family_id=q.scope_id and f.active join maths.runtime_questions r on r.question_id=f.question_id and r.runtime_active left join maths.question_state st on st.user_id=p_uid and st.question_id=r.question_id
union all select q.repair_id,q.priority,q.priority_score,q.question_id,r.question_id,row_number()over(partition by q.repair_id order by(r.question_id<>coalesce(q.question_id,''))desc,(coalesce(st.mastered,false)=false)desc,coalesce(st.attempts,0),abs(hashtext(r.question_id||q.repair_id::text)))from queue q join maths.question_concepts c on q.scope_type='concept' and c.concept_id=q.scope_id and c.active join maths.runtime_questions r on r.question_id=c.question_id and r.runtime_active left join maths.question_state st on st.user_id=p_uid and st.question_id=r.question_id
union all select q.repair_id,q.priority,q.priority_score,q.question_id,r.question_id,1 from queue q join maths.runtime_questions r on q.scope_type='question' and r.question_id=q.scope_id and r.runtime_active),ranked as(select distinct on(question_id)question_id,case priority when 'P0' then 1 when 'P1' then 2 when 'P2' then 3 else 4 end p,priority_score,family_rank from candidates where family_rank<=3 order by question_id,p,priority_score desc,family_rank)
select coalesce(array_agg(question_id order by p,priority_score desc,family_rank),array[]::text[])from(select * from ranked order by p,priority_score desc,family_rank limit greatest(1,least(coalesce(p_count,5),30)))x$$;

create or replace function maths._select_daily_ids_v45(p_uid uuid,p_day integer,p_size integer,p_exclude text[] default array[]::text[])returns text[] language plpgsql stable security definer set search_path='pg_catalog','public','maths' as $$declare repairs text[]:=array[]::text[];rest text[]:=array[]::text[];repair_limit int;begin repair_limit:=greatest(1,least(6,ceil(greatest(1,p_size)*.24)::int));repairs:=maths._repair_candidate_ids(p_uid,repair_limit,null);repairs:=array(select x from unnest(coalesce(repairs,array[]::text[]))x where not x=any(coalesce(p_exclude,array[]::text[])));rest:=maths._select_daily_ids(p_uid,p_day,greatest(0,p_size-coalesce(array_length(repairs,1),0)),coalesce(p_exclude,array[]::text[])||coalesce(repairs,array[]::text[]));return coalesce(repairs,array[]::text[])||coalesce(rest,array[]::text[]);end$$;

create or replace function public.maths_get_repair_queue(p_limit integer default 20)returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();items jsonb;due_ int;p0_ int;p1_ int;cold_ int;begin select count(*)filter(where status in('open','waiting_confirmation')and due_at<=now()),count(*)filter(where status in('open','waiting_confirmation')and priority='P0'),count(*)filter(where status in('open','waiting_confirmation')and priority='P1')into due_,p0_,p1_ from maths.repair_queue where user_id=uid;select count(*)into cold_ from maths.family_state where user_id=uid and last_negative_at is not null and not cold_confirmed;select coalesce(jsonb_agg(jsonb_build_object('repairId',repair_id,'scopeType',scope_type,'scopeId',scope_id,'questionId',question_id,'reason',reason,'priority',priority,'status',status,'score',priority_score,'dueAt',due_at,'diagnosisNeeded',coalesce((metadata->>'diagnosisNeeded')::boolean,false),'label',case scope_type when 'family' then coalesce((select family_name from maths.family_catalog f where f.family_id=scope_id),scope_id)when 'concept' then coalesce((select concept_name from maths.concept_catalog c where c.concept_id=scope_id),scope_id)else scope_id end)order by case priority when 'P0' then 1 when 'P1' then 2 when 'P2' then 3 else 4 end,priority_score desc,due_at),'[]'::jsonb)into items from(select * from maths.repair_queue where user_id=uid and status in('open','waiting_confirmation')order by case priority when 'P0' then 1 when 'P1' then 2 when 'P2' then 3 else 4 end,priority_score desc,due_at limit greatest(1,least(coalesce(p_limit,20),100)))x;return jsonb_build_object('ok',true,'due',coalesce(due_,0),'p0',coalesce(p0_,0),'p1',coalesce(p1_,0),'coldPending',coalesce(cold_,0),'items',items);end$$;

create or replace function public.maths_start_repair(p_count integer default 5,p_reason text default null)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();ids text[];out_ jsonb;begin ids:=maths._repair_candidate_ids(uid,greatest(1,least(coalesce(p_count,5),20)),nullif(upper(p_reason),''));out_:=maths._start_session(uid,ids,'repair','Targeted Repair'||case when p_reason is null then '' else ' · '||upper(p_reason)end,jsonb_build_object('reason',upper(p_reason),'repair',true,'transferFirst',true),false);if coalesce(out_->>'sessionId','')<>'' then update maths.repair_queue set status='in_progress',repair_attempts=repair_attempts+1,last_repair_at=now(),updated_at=now()where user_id=uid and status in('open','waiting_confirmation')and(due_at<=now() or priority='P0')and(p_reason is null or reason=upper(p_reason));end if;return out_;end$$;

create or replace function public.maths_start_mixed(p_count integer default 20)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();day_ int:=maths._study_day();ids text[];repairs text[];rest text[];begin repairs:=maths._repair_candidate_ids(uid,least(6,greatest(2,coalesce(p_count,20)/4)),null);rest:=maths._select_daily_ids(uid,day_,greatest(0,least(coalesce(p_count,20),50)-coalesce(array_length(repairs,1),0)),coalesce(repairs,array[]::text[]));ids:=coalesce(repairs,array[]::text[])||coalesce(rest,array[]::text[]);return maths._start_session(uid,ids,'mixed_transfer','Mixed Practice · Transfer',jsonb_build_object('mixedTransfer',true,'repairCount',coalesce(array_length(repairs,1),0)),false);end$$;

create or replace function public.maths_start_daily()returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();day_ int:=maths._study_day();s maths.sessions%rowtype;size_ int:=greatest(1,coalesce(nullif(maths._setting('daily_chapter_size','25'),'')::int,25));ids text[];comp jsonb;repair_n int;begin perform pg_advisory_xact_lock(hashtext(uid::text||':maths-daily:'||day_::text));select * into s from maths.sessions where user_id=uid and lower(coalesce(mode,''))='daily' and coalesce(nullif(params->>'planDay','')::int,0)=day_ order by completed desc,updated_at desc nulls last limit 1;if found then if not s.completed then return maths._get_session(uid,s.session_id);else return jsonb_build_object('ok',false,'dailyComplete',true,'message','Day '||day_||' is complete. Use Practice More for another mixed set.','sessionId',s.session_id);end if;end if;ids:=maths._select_daily_ids_v45(uid,day_,size_,array[]::text[]);select count(*)into repair_n from unnest(ids)x(id)where exists(select 1 from maths.repair_queue rq left join maths.question_families qf on rq.scope_type='family' and qf.family_id=rq.scope_id and qf.question_id=x.id left join maths.question_concepts qc on rq.scope_type='concept' and qc.concept_id=rq.scope_id and qc.question_id=x.id where rq.user_id=uid and rq.status in('open','in_progress','waiting_confirmation')and(rq.question_id=x.id or qf.question_id is not null or qc.question_id is not null));with rr as(select r.*,count(*)over(partition by r.chapter)cnt from maths._user_runtime(uid)r where r.question_id=any(ids)),ch as(select jsonb_object_agg(chapter,cnt)chapters from(select distinct chapter,cnt from rr)x)select jsonb_build_object('repair',coalesce(repair_n,0),'new',count(*)filter(where rr.state_attempts=0),'difficultDue',count(*)filter(where rr.difficult),'hard',count(*)filter(where rr.hard),'weak',count(*)filter(where rr.weak),'dueRevision',count(*)filter(where rr.profile_total>0 and rr.age_days>=rr.review_interval),'chapters',coalesce((select chapters from ch),'{}'::jsonb))into comp from rr;return maths._start_session(uid,ids,'daily','Day '||day_||' · Mixed Revision',jsonb_build_object('planDay',day_,'planChapter','Mixed Revision','dailyComposition',comp,'dailyVersion','v45-repair'),false);end$$;

create or replace function maths._sprint_ids(p_uid uuid,p_count integer default 25)returns text[] language sql stable security definer set search_path='pg_catalog','public','maths' as $$with eligible as(select r.question_id,r.chapter,row_number()over(partition by r.chapter order by r.in_mock desc,(r.profile_total=0)desc,abs(hashtext(r.question_id||clock_timestamp()::text)))rn from maths._user_runtime(p_uid)r where r.academic_eligible and r.runtime_active),balanced as(select question_id,rn,abs(hashtext(question_id||clock_timestamp()::text))h from eligible order by rn,h limit greatest(1,least(coalesce(p_count,25),25)))select coalesce(array_agg(question_id order by rn,h),array[]::text[])from balanced$$;
create or replace function public.maths_start_sprint(p_diagnostic boolean default false)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();ids text[];begin ids:=maths._sprint_ids(uid,25);return maths._start_session(uid,ids,'section_sprint','SSC Maths Section Sprint',jsonb_build_object('durationSec',900,'questionCount',25,'marksCorrect',2,'marksWrong',-.5,'selectionCapture',coalesce(p_diagnostic,false),'examMode',true),false);end$$;
create or replace function maths._session_score(p_uid uuid,p_session_id text)returns numeric language sql stable security definer set search_path='pg_catalog','public','maths' as $$select round(2*count(*)filter(where lower(a.result)='correct')-.5*count(*)filter(where lower(a.result)='wrong'),2)from maths.attempts a where a.user_id=p_uid and a.session_id=p_session_id$$;
create or replace function maths._sprint_stability(p_uid uuid)returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','maths' as $$declare out_ jsonb;begin with last_sprints as(select s.session_id,s.created_at,maths._session_score(p_uid,s.session_id)score,(select count(*)from maths.attempts a where a.user_id=p_uid and a.session_id=s.session_id)attempted,(select avg(a.response_sec)from maths.attempts a where a.user_id=p_uid and a.session_id=s.session_id and a.response_sec>0)avg_sec from maths.sessions s where s.user_id=p_uid and lower(coalesce(s.mode,''))='section_sprint' and s.completed order by s.updated_at desc limit 10)select jsonb_build_object('count',count(*),'best',max(score),'median',round(percentile_cont(.5)within group(order by score)::numeric,2),'badDayFloor',round(percentile_cont(.2)within group(order by score)::numeric,2),'range',case when count(*)>0 then jsonb_build_array(min(score),max(score))else'[]'::jsonb end,'variance',round(coalesce(var_pop(score),0),2),'attemptedAvg',round(avg(attempted),1),'avgSec',round(avg(avg_sec),1),'scores',coalesce(jsonb_agg(jsonb_build_object('score',score,'at',created_at)order by created_at),'[]'::jsonb))into out_ from last_sprints;return coalesce(out_,jsonb_build_object('count',0));end$$;

create or replace function public.maths_get_sprint_analysis(p_session_id text)returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();s maths.sessions%rowtype;score_ numeric;correct_ int;wrong_ int;unattempted_ int;recover_ numeric;reasons_ jsonb;good_skip_ int;bad_skip_ int;traps_ int;best_reason text;stability_ jsonb;begin select * into s from maths.sessions where session_id=p_session_id and user_id=uid and lower(coalesce(mode,''))='section_sprint';if not found then raise exception 'Sprint not found';end if;score_:=maths._session_score(uid,p_session_id);with rows as(select sq.question_id,a.result,a.response_sec,coalesce(pe.final_reason,case when pe.slow_correct then 'TIME' end)reason,maths._baseline_sec(uid,sq.question_id,coalesce(a.attempted_at,now()))baseline,se.decision,se.decision_sec,coalesce(st.mastered,false)mastered,lower(coalesce(st.last_result,''))last_state_result from maths.session_questions sq left join maths.attempts a on a.user_id=uid and a.session_id=p_session_id and a.question_id=sq.question_id left join lateral(select * from maths.performance_evidence e where e.user_id=uid and e.session_id=p_session_id and e.question_id=sq.question_id order by created_at desc limit 1)pe on true left join maths.selection_evidence se on se.user_id=uid and se.session_id=p_session_id and se.question_id=sq.question_id left join maths.question_state st on st.user_id=uid and st.question_id=sq.question_id where sq.session_id=p_session_id)select count(*)filter(where result='correct'),count(*)filter(where result='wrong'),count(*)filter(where result is null),count(*)filter(where result is null and coalesce(decision,'')in('SKIP','LATER')and baseline>=40 and not mastered),count(*)filter(where result is null and(mastered or last_state_result='correct')and baseline<=35),count(*)filter(where result='wrong' and response_sec>baseline*1.5),round(2.5*count(*)filter(where result='wrong' and reason in('CAL','SILLY','TIME')and(mastered or last_state_result='correct'))+2*count(*)filter(where result is null and(mastered or last_state_result='correct')and baseline<=35),1)into correct_,wrong_,unattempted_,good_skip_,bad_skip_,traps_,recover_ from rows;select coalesce(jsonb_object_agg(reason,n),'{}'::jsonb),(array_agg(reason order by n desc,reason))[1]into reasons_,best_reason from(select coalesce(pe.final_reason,case when pe.slow_correct then 'TIME' end)reason,count(*)n from maths.performance_evidence pe where pe.user_id=uid and pe.session_id=p_session_id and(pe.correctness='wrong' or pe.slow_correct)and coalesce(pe.final_reason,case when pe.slow_correct then 'TIME' end)is not null group by 1)x;stability_:=maths._sprint_stability(uid);return jsonb_build_object('ok',true,'sessionId',p_session_id,'score',score_,'maxScore',50,'correct',coalesce(correct_,0),'wrong',coalesce(wrong_,0),'unattempted',coalesce(unattempted_,0),'recoverableMarksEstimate',coalesce(recover_,0),'reasons',coalesce(reasons_,'{}'::jsonb),'selection',jsonb_build_object('goodSkips',coalesce(good_skip_,0),'badSkips',coalesce(bad_skip_,0),'timeTraps',coalesce(traps_,0)),'bestNextAction',case coalesce(best_reason,'')when'APP'then'5-question Approach Repair'when'CAL'then'10-minute Calculation Drill'when'TIME'then'Timed Method Repair'when'FOR'then'Formula Active Recall'when'CON'then'Concept Repair'when'SILLY'then'Trap-focused Repair'else'Mixed Transfer Repair'end,'stability',stability_);end$$;

create or replace function maths._calculation_ids(p_uid uuid,p_count integer,p_skill text default null)returns text[] language sql stable security definer set search_path='pg_catalog','public','maths' as $$with c as(select r.question_id,coalesce(nullif(q.topic,''),nullif(q.subtopic,''),'Mixed')skill,case when r.profile_last_result='wrong' then 70 else 0 end+case when r.last_response_sec>greatest(6,r.expected_sec*.35)then 35 else 0 end+coalesce((select 20*count(*)from maths.performance_evidence e where e.user_id=p_uid and e.question_id=r.question_id and e.created_at>=now()-interval '14 days' and(e.final_reason='CAL' or e.slow_correct)),0)score,row_number()over(partition by coalesce(nullif(q.topic,''),nullif(q.subtopic,''),'Mixed')order by(r.profile_last_result='wrong')desc,r.last_response_sec desc,random())skill_rank from maths._user_runtime(p_uid)r join maths.runtime_questions q using(question_id)where r.runtime_active and(r.bank_calculation or r.in_calc_set)and maths._calc_type(q)in('METHOD','DRILL')and(p_skill is null or maths._norm(coalesce(q.topic,q.subtopic,'Mixed'))=maths._norm(p_skill)))select coalesce(array_agg(question_id order by skill_rank,score desc,random()),array[]::text[])from(select * from c order by skill_rank,score desc,random() limit greatest(1,least(coalesce(p_count,30),80)))x$$;

create or replace function public.maths_start_calculation(p_mode text default 'timed',p_type text default null,p_skill text default null,p_count integer default 30)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();base text[];ids text[];mode_ text:=lower(coalesce(p_mode,'timed'));force_reveal boolean:=mode_='recall';out_ jsonb;sid_ text;begin if mode_='timed'then ids:=maths._calculation_ids(uid,greatest(30,least(coalesce(p_count,30),80)),p_skill);return maths._start_session(uid,ids,'calculation_speed','10-Min Calculation Drill',jsonb_build_object('mode','timed','skill',p_skill,'durationSec',600,'calculationTimed',true,'refillBatch',20),false);end if;with c as(select r.question_id,r.profile_last_result,r.difficult,r.last_response_sec,r.state_attempts,maths._calc_type(q)typ,maths._norm(coalesce(q.topic,q.subtopic,'Mixed'))skill from maths._user_runtime(uid)r join maths.runtime_questions q using(question_id)where r.runtime_active and(r.bank_calculation or r.in_calc_set)and(maths._calc_type(q)<>'MEMORY' or maths._calc_recall_eligible(q)))select coalesce(array_agg(question_id),array[]::text[])into base from c where(p_type is null or typ=upper(p_type))and(p_skill is null or skill=maths._norm(p_skill))and(mode_<>'recall' or typ='MEMORY');if mode_ in('weak','slow')then select coalesce(array_agg(x.question_id),array[]::text[])into ids from(select r.question_id from maths._user_runtime(uid)r where r.question_id=any(base)order by(r.profile_last_result='wrong')desc,r.difficult desc,(r.last_response_sec>=8)desc,(r.state_attempts=0)desc,r.last_response_sec desc limit greatest(1,least(coalesce(p_count,20),100)))x;elsif mode_='all'then ids:=base;else select coalesce(array_agg(x),array[]::text[])into ids from(select unnest(base)x order by random()limit greatest(1,least(coalesce(p_count,20),100)))z;end if;if mode_='mixed'then out_:=maths._start_session(uid,ids,'calculation_speed','Calculation Training · Mixed Practice',jsonb_build_object('mode',mode_,'type',p_type,'skill',p_skill),false);sid_:=out_->>'sessionId';if sid_ is not null then update maths.sessions s set rendered_questions=(select jsonb_agg(case when maths._calc_type(q)='MEMORY'then(e-'options'-'correctOption'-'answerMode'-'variantType')||jsonb_build_object('options','[]'::jsonb,'correctOption','','answerMode','REVEAL','variantType','CALC_RECALL')else e end order by ord)from jsonb_array_elements(s.rendered_questions)with ordinality z(e,ord)join maths.runtime_questions q on q.question_id=e->>'questionId')where s.session_id=sid_ and s.user_id=uid;return maths._get_session(uid,sid_);end if;return out_;end if;return maths._start_session(uid,ids,'calculation_speed','Calculation Training · '||case when mode_='recall'then'Recall'when mode_ in('weak','slow')then'Weak & Slow'when mode_='all'then'All'else'Mixed Practice'end,jsonb_build_object('mode',mode_,'type',p_type,'skill',p_skill),force_reveal);end$$;

create or replace function public.maths_refill_calculation_session(p_session_id text,p_count integer default 20)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();s maths.sessions%rowtype;existing text[];ids text[];qid text;pos_ int;rendered jsonb;begin perform pg_advisory_xact_lock(hashtext(uid::text||':'||p_session_id||':calc-refill'));select * into s from maths.sessions where session_id=p_session_id and user_id=uid and lower(coalesce(mode,''))='calculation_speed';if not found or coalesce((s.params->>'calculationTimed')::boolean,false)=false then raise exception 'Timed calculation session not found';end if;if s.completed then return maths._get_session(uid,p_session_id);end if;select coalesce(array_agg(question_id),array[]::text[])into existing from maths.session_questions where session_id=p_session_id;ids:=array(select x from unnest(maths._calculation_ids(uid,greatest(30,least(coalesce(p_count,20)*3,80)),nullif(s.params->>'skill','')))x where not x=any(existing)limit greatest(1,least(coalesce(p_count,20),40)));if coalesce(array_length(ids,1),0)=0 then return maths._get_session(uid,p_session_id);end if;select coalesce(max(position),-1)+1 into pos_ from maths.session_questions where session_id=p_session_id;foreach qid in array ids loop insert into maths.session_questions(session_id,question_id,position)values(p_session_id,qid,pos_);pos_:=pos_+1;end loop;rendered:=maths._render_questions(uid,ids,false);update maths.sessions set rendered_questions=coalesce(rendered_questions,'[]'::jsonb)||rendered,updated_at=now()where session_id=p_session_id and user_id=uid;return maths._get_session(uid,p_session_id);end$$;

create or replace function public.maths_get_calculation_summary(p_session_id text)returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();s maths.sessions%rowtype;attempted_ int;correct_ int;wrong_ int;med_ numeric;p75_ numeric;p90_ numeric;elapsed_ numeric;qpm_ numeric;skills_ jsonb;begin select * into s from maths.sessions where session_id=p_session_id and user_id=uid and lower(coalesce(mode,''))='calculation_speed';if not found then raise exception 'Calculation session not found';end if;elapsed_:=least(coalesce(nullif(s.params->>'durationSec','')::numeric,600),greatest(1,extract(epoch from(coalesce(nullif(s.params->>'finishedAt','')::timestamptz,now())-s.created_at))));select count(*),count(*)filter(where result='correct'),count(*)filter(where result='wrong'),percentile_cont(.5)within group(order by response_sec)filter(where response_sec>0),percentile_cont(.75)within group(order by response_sec)filter(where response_sec>0),percentile_cont(.90)within group(order by response_sec)filter(where response_sec>0)into attempted_,correct_,wrong_,med_,p75_,p90_ from maths.attempts where user_id=uid and session_id=p_session_id and result in('correct','wrong');qpm_:=case when elapsed_>0 then round(coalesce(attempted_,0)/(elapsed_/60),2)else 0 end;select coalesce(jsonb_agg(jsonb_build_object('skill',skill,'attempted',n,'accuracy',round(100*correct::numeric/nullif(n,0),1),'medianSec',round(median_sec,1),'baselineSec',round(baseline_sec,1),'band',case when n>=3 and 100*correct::numeric/nullif(n,0)>=95 and median_sec<=baseline_sec*.8 then'Automatic'when n>=3 and 100*correct::numeric/nullif(n,0)>=90 and median_sec<=baseline_sec then'Strong'when n>=2 and 100*correct::numeric/nullif(n,0)>=80 then'Almost there'else'Needs work'end)order by n desc,skill),'[]'::jsonb)into skills_ from(select coalesce(nullif(q.topic,''),nullif(q.subtopic,''),'Mixed')skill,count(*)n,count(*)filter(where a.result='correct')correct,percentile_cont(.5)within group(order by a.response_sec)median_sec,percentile_cont(.5)within group(order by maths._baseline_sec(uid,a.question_id,a.attempted_at))baseline_sec from maths.attempts a join maths.runtime_questions q on q.question_id=a.question_id where a.user_id=uid and a.session_id=p_session_id and a.result in('correct','wrong')and a.response_sec>0 group by 1)x;return jsonb_build_object('ok',true,'sessionId',p_session_id,'attempted',coalesce(attempted_,0),'correct',coalesce(correct_,0),'wrong',coalesce(wrong_,0),'accuracy',case when attempted_>0 then round(100*correct_::numeric/attempted_,1)else 0 end,'qpm',coalesce(qpm_,0),'medianSec',round(coalesce(med_,0),1),'p75Sec',round(coalesce(p75_,0),1),'p90Sec',round(coalesce(p90_,0),1),'elapsedSec',round(coalesce(elapsed_,0),1),'skills',skills_);end$$;

create or replace function public.maths_get_calculation_hub()returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();hub jsonb;focus_ jsonb;begin with c as(select r.*,maths._calc_type(q)calc_type,coalesce(nullif(q.topic,''),nullif(q.subtopic,''),'Mixed')skill from maths._user_runtime(uid)r join maths.runtime_questions q using(question_id)where r.runtime_active and(r.bank_calculation or r.in_calc_set)and(maths._calc_type(q)<>'MEMORY' or maths._calc_recall_eligible(q))),skill_perf as(select c.skill,count(*)total,count(*)filter(where calc_type='MEMORY')memory,count(*)filter(where calc_type='METHOD')methods,count(*)filter(where calc_type='DRILL')drills,count(*)filter(where c.profile_total>0)attempted,avg(c.profile_accuracy)filter(where c.profile_graded>0)accuracy,percentile_cont(.5)within group(order by nullif(c.last_response_sec,0))median_sec,percentile_cont(.5)within group(order by c.expected_sec)baseline_sec,count(*)filter(where c.profile_last_result='wrong' or c.last_response_sec>c.expected_sec)leakage from c group by c.skill)select jsonb_build_object('ok',true,'total',count(*),'memory',count(*)filter(where calc_type='MEMORY'),'methods',count(*)filter(where calc_type='METHOD'),'drills',count(*)filter(where calc_type='DRILL'),'slow',count(*)filter(where last_response_sec>=8),'wrong',count(*)filter(where profile_last_result='wrong'),'durationSec',600,'skills',coalesce((select jsonb_agg(jsonb_build_object('skill',skill,'total',total,'memory',memory,'methods',methods,'drills',drills,'attempted',attempted,'accuracy',case when accuracy is null then null else round(100*accuracy,1)end,'medianSec',round(coalesce(median_sec,0),1),'baselineSec',round(coalesce(baseline_sec,0),1),'band',case when attempted>=3 and coalesce(accuracy,0)>=.95 and coalesce(median_sec,999)<=coalesce(baseline_sec,30)*.8 then'Automatic'when attempted>=3 and coalesce(accuracy,0)>=.90 and coalesce(median_sec,999)<=coalesce(baseline_sec,30)then'Strong'when attempted>=2 and coalesce(accuracy,0)>=.80 then'Almost there'else'Needs work'end)order by leakage desc,skill)from skill_perf),'[]'::jsonb))into hub from c;select coalesce(jsonb_agg(skill order by leakage desc,skill),'[]'::jsonb)into focus_ from(select skill,leakage from(select coalesce(nullif(q.topic,''),nullif(q.subtopic,''),'Mixed')skill,count(*)filter(where r.profile_last_result='wrong' or r.last_response_sec>r.expected_sec)leakage from maths._user_runtime(uid)r join maths.runtime_questions q using(question_id)where r.runtime_active and(r.bank_calculation or r.in_calc_set)and maths._calc_type(q)in('METHOD','DRILL')group by 1)z order by leakage desc,skill limit 2)x;return hub||jsonb_build_object('todayFocus',focus_);end$$;

create or replace function public.maths_finish_session(p_session_id text)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();total_ int;done_ int;s maths.sessions%rowtype;partial_ok boolean;begin select * into s from maths.sessions where session_id=p_session_id and user_id=uid;if not found then raise exception 'Session not found';end if;select count(*)into total_ from maths.session_questions where session_id=p_session_id;select count(distinct question_id)into done_ from maths.attempts where user_id=uid and session_id=p_session_id;partial_ok:=lower(coalesce(s.mode,''))='section_sprint' or(lower(coalesce(s.mode,''))='calculation_speed' and coalesce((s.params->>'calculationTimed')::boolean,false));if not partial_ok and done_<total_ then raise exception 'Session is incomplete (% of % answered)',done_,total_;end if;update maths.sessions set completed=true,current_index=greatest(0,least(current_index,greatest(0,total_-1))),updated_at=now(),params=jsonb_set(coalesce(params,'{}'::jsonb),'{finishedAt}',to_jsonb(now()::text),true)where session_id=p_session_id and user_id=uid;return jsonb_build_object('ok',true,'completed',true,'done',done_,'target',total_,'partial',done_<total_);end$$;

create or replace function public.maths_get_approach_hub(p_limit integer default 30)returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();cards jsonb;weak_ int;begin select count(*)into weak_ from maths.family_state where user_id=uid and persistent_weak;with personal as(select a.family_id,a.pattern,a.trigger_text,a.first_thought,a.fast_method,a.trap,'personal'source,coalesce(fs.persistent_weak,false)persistent_weak,coalesce(fs.recent_accuracy,1)accuracy,a.updated_at from maths.approach_cards a left join maths.family_state fs on fs.user_id=uid and fs.family_id=a.family_id where a.user_id=uid and a.active and a.family_id is not null),seeded as(select f.family_id,f.family_name pattern,f.recognition_trigger trigger_text,null::text first_thought,f.common_method fast_method,null::text trap,'template'source,coalesce(fs.persistent_weak,false),coalesce(fs.recent_accuracy,1),f.updated_at from maths.family_catalog f left join maths.family_state fs on fs.user_id=uid and fs.family_id=f.family_id where f.active and nullif(btrim(f.recognition_trigger),'')is not null and not exists(select 1 from personal p where p.family_id=f.family_id)),all_cards as(select * from personal union all select * from seeded)select coalesce(jsonb_agg(jsonb_build_object('familyId',family_id,'pattern',pattern,'trigger',trigger_text,'firstThought',first_thought,'fastMethod',fast_method,'trap',trap,'source',source,'persistentWeak',persistent_weak,'accuracy',round(100*accuracy,1))order by persistent_weak desc,accuracy asc,updated_at desc),'[]'::jsonb)into cards from(select * from all_cards order by persistent_weak desc,accuracy asc,updated_at desc limit greatest(1,least(coalesce(p_limit,30),100)))x;return jsonb_build_object('ok',true,'persistentWeak',coalesce(weak_,0),'cards',cards);end$$;
create or replace function public.maths_record_approach_recall(p_family_id text,p_got_approach boolean,p_recognition_sec numeric default null)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();qid text;begin if not exists(select 1 from maths.family_catalog where family_id=p_family_id and active)then raise exception 'Approach family not found';end if;insert into maths.approach_recall_evidence(user_id,family_id,got_approach,recognition_sec)values(uid,p_family_id,p_got_approach,greatest(0,least(coalesce(p_recognition_sec,0),300)));if not p_got_approach then select question_id into qid from maths.question_families where family_id=p_family_id and active order by question_id limit 1;update maths.repair_queue set status='dismissed',updated_at=now()where user_id=uid and scope_type='family' and scope_id=p_family_id and status='open' and reason='APP';insert into maths.repair_queue(user_id,scope_type,scope_id,question_id,reason,priority,status,priority_score,due_at,next_confirmation_at,metadata)values(uid,'family',p_family_id,qid,'APP','P1','open',82,now(),now()+interval '20 hours',jsonb_build_object('source','approach_recall'));end if;return jsonb_build_object('ok',true,'familyId',p_family_id,'gotApproach',p_got_approach);end$$;
create or replace function public.maths_save_approach_card(p_family_id text,p_pattern text,p_trigger text default null,p_first_thought text default null,p_fast_method text default null,p_trap text default null)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();id_ uuid;begin if not exists(select 1 from maths.family_catalog where family_id=p_family_id and active)then raise exception 'Approach family not found';end if;select card_id into id_ from maths.approach_cards where user_id=uid and family_id=p_family_id and active order by updated_at desc limit 1;if id_ is null then insert into maths.approach_cards(user_id,family_id,pattern,trigger_text,first_thought,fast_method,trap,source)values(uid,p_family_id,left(btrim(p_pattern),300),left(p_trigger,500),left(p_first_thought,500),left(p_fast_method,800),left(p_trap,500),'personal')returning card_id into id_;else update maths.approach_cards set pattern=left(btrim(p_pattern),300),trigger_text=left(p_trigger,500),first_thought=left(p_first_thought,500),fast_method=left(p_fast_method,800),trap=left(p_trap,500),updated_at=now()where card_id=id_ and user_id=uid;end if;return jsonb_build_object('ok',true,'cardId',id_);end$$;

create or replace function public.maths_stage_external_mock(p_payload jsonb,p_source_label text default null,p_source_ref text default null)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();prompt_ text;norm_ text;match_ text;matches_ int;sid uuid;e_id uuid;result_ text;response_ numeric;reason_ text;user_reason_ text;concept_ text;family_ text;begin prompt_:=coalesce(nullif(btrim(p_payload->>'prompt'),''),nullif(btrim(p_payload->>'question'),''));if prompt_ is null then raise exception 'External mock payload requires prompt/question text';end if;norm_:=lower(regexp_replace(regexp_replace(prompt_,'\s+',' ','g'),'[^a-zA-Z0-9%./:+*?() -]','','g'));select count(*),min(question_id)into matches_,match_ from maths.runtime_questions where runtime_active and lower(regexp_replace(regexp_replace(prompt,'\s+',' ','g'),'[^a-zA-Z0-9%./:+*?() -]','','g'))=norm_;insert into maths.external_mock_staging(user_id,source_label,source_ref,extracted_payload,normalized_prompt,matched_question_id,match_confidence,match_method,review_status)values(uid,p_source_label,p_source_ref,p_payload,norm_,case when matches_=1 then match_ else null end,case when matches_=1 then 1 else null end,case when matches_=1 then'normalized_exact_prompt'else null end,case when matches_=1 then'matched'else'needs_review'end)returning stage_id into sid;if matches_=1 and lower(coalesce(p_payload->>'result',''))in('correct','wrong','seen')then result_:=lower(p_payload->>'result');response_:=greatest(0,least(coalesce(nullif(p_payload->>'responseSec','')::numeric,0),86400));reason_:=upper(nullif(p_payload->>'inferredReason',''));user_reason_:=upper(nullif(p_payload->>'userReason',''));if reason_ not in('CAL','APP','CON','FOR','SILLY','TIME')then reason_:=null;end if;if user_reason_ not in('CAL','APP','CON','FOR','SILLY','TIME')then user_reason_:=null;end if;insert into maths.performance_evidence(user_id,question_id,session_id,evidence_source,inferred_reason,user_confirmed_reason,inference_confidence,correctness,response_sec,baseline_sec,timing_class,slow_correct,confidence_response,metadata)values(uid,match_,null,'external_mock',reason_,user_reason_,case when reason_ is null then null else .65 end,result_,response_,maths._baseline_sec(uid,match_,now()),maths._timing_class(result_,response_,maths._baseline_sec(uid,match_,now())),maths._timing_class(result_,response_,maths._baseline_sec(uid,match_,now()))='correct_slow',case when lower(coalesce(p_payload->>'confidence',''))in('sure','50_50','guess')then lower(p_payload->>'confidence')else null end,jsonb_build_object('stageId',sid,'sourceLabel',p_source_label,'sourceRef',p_source_ref))returning evidence_id into e_id;select concept_id into concept_ from maths.question_concepts where question_id=match_ and active order by confidence desc limit 1;if concept_ is not null then perform maths._refresh_concept_state(uid,concept_);end if;select family_id into family_ from maths.question_families where question_id=match_ and active limit 1;if family_ is not null then perform maths._refresh_family_state(uid,family_);end if;perform maths._sync_repair_from_evidence(e_id);end if;return jsonb_build_object('ok',true,'stageId',sid,'status',case when matches_=1 then'matched'else'needs_review'end,'matchedQuestionId',case when matches_=1 then match_ else null end,'matchConfidence',case when matches_=1 then 1 else null end);end$$;
create or replace function public.maths_resolve_external_mock_stage(p_stage_id uuid,p_question_id text,p_match_confidence numeric default 1)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();begin if not exists(select 1 from maths.runtime_questions where question_id=p_question_id and runtime_active)then raise exception 'Canonical question not found';end if;update maths.external_mock_staging set matched_question_id=p_question_id,match_confidence=greatest(0,least(coalesce(p_match_confidence,1),1)),match_method='review_confirmed',review_status='resolved',resolved_at=now()where stage_id=p_stage_id and user_id=uid;if not found then raise exception 'External mock stage not found';end if;return jsonb_build_object('ok',true,'stageId',p_stage_id,'matchedQuestionId',p_question_id,'status','resolved');end$$;

create or replace function public.maths_get_readiness()returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();day_ int:=greatest(1,least(30,maths._study_day()));phase_ int;graded_ int;correct_ int;clean_ int;knowledge_ numeric;performance_ numeric;reasons_ jsonb;diagnosis_ int;p0_ int;due_ int;persistent_ int;cold_ int;sprint_ jsonb;top_reason text;recommendations jsonb;begin phase_:=case when day_<=7 then 1 when day_<=15 then 2 when day_<=23 then 3 else 4 end;with recent as(select * from maths.performance_evidence where user_id=uid and created_at>=now()-interval '30 days' and correctness in('correct','wrong'))select count(*),count(*)filter(where correctness='correct'),count(*)filter(where correctness='correct' and not slow_correct),count(*)filter(where correctness='wrong' and final_reason is null)into graded_,correct_,clean_,diagnosis_ from recent;knowledge_:=case when graded_>0 then round(100*correct_::numeric/graded_,1)else 0 end;performance_:=case when graded_>0 then round(100*clean_::numeric/graded_,1)else 0 end;select coalesce(jsonb_object_agg(reason,n),'{}'::jsonb),(array_agg(reason order by n desc,reason))[1]into reasons_,top_reason from(select final_reason reason,count(*)n from maths.performance_evidence where user_id=uid and created_at>=now()-interval '14 days' and(correctness='wrong' or slow_correct)and final_reason is not null group by final_reason)x;select count(*)filter(where priority='P0' and status in('open','waiting_confirmation')),count(*)filter(where due_at<=now() and status in('open','waiting_confirmation'))into p0_,due_ from maths.repair_queue where user_id=uid;select count(*)into persistent_ from maths.family_state where user_id=uid and persistent_weak;select count(*)into cold_ from maths.family_state where user_id=uid and cold_confirmed;sprint_:=maths._sprint_stability(uid);recommendations:=jsonb_build_array(jsonb_build_object('kind','calculation','label','10m Calculation','href','/maths/calculation','priority',case when coalesce((reasons_->>'CAL')::int,0)>0 then 1 else 3 end),jsonb_build_object('kind','repair','label',greatest(3,least(5,coalesce(due_,0)))||' Repairs','href','/maths/repair','priority',case when coalesce(p0_,0)>0 or coalesce(due_,0)>0 then 1 else 4 end),jsonb_build_object('kind','sprint','label','25Q Section Sprint','href','/maths/sprint','priority',case when phase_>=3 then 1 else 3 end),jsonb_build_object('kind','approach','label','Approach Scan','href','/maths/approach','priority',case when coalesce((reasons_->>'APP')::int,0)>0 or persistent_>0 then 2 else 4 end));return jsonb_build_object('ok',true,'studyDay',day_,'phase',phase_,'phaseLabel',case phase_ when 1 then'Diagnosis + leakage removal'when 2 then'Speed conversion'when 3 then'Exam transfer'else'Score stabilization'end,'knowledge',jsonb_build_object('score',knowledge_,'graded',coalesce(graded_,0),'correct',coalesce(correct_,0),'coldConfirmedFamilies',coalesce(cold_,0)),'performance',jsonb_build_object('score',performance_,'cleanCorrect',coalesce(clean_,0),'slowOrWrong',greatest(0,coalesce(graded_,0)-coalesce(clean_,0))),'repair',jsonb_build_object('p0',coalesce(p0_,0),'due',coalesce(due_,0),'persistentFamilies',coalesce(persistent_,0),'diagnosisPending',coalesce(diagnosis_,0)),'leakage',coalesce(reasons_,'{}'::jsonb),'biggestLeak',top_reason,'sprint',sprint_,'recommendations',recommendations);end$$;

create or replace function maths._render_questions(p_uid uuid,p_ids text[],p_force_memory_reveal boolean default false)returns jsonb language sql stable security definer set search_path='pg_catalog','public','maths' as $$with src as(select r.*,u.ord,upper(coalesce(r.correct_option,''))ckey,upper(coalesce(st.last_correct_option,''))last_key,jsonb_build_object('A',coalesce(r.option_a,''),'B',coalesce(r.option_b,''),'C',coalesce(r.option_c,''),'D',coalesce(r.option_d,''))omap,(select family_id from maths.question_families f where f.question_id=r.question_id and f.active limit 1)family_id,(select concept_id from maths.question_concepts c where c.question_id=r.question_id and c.active order by confidence desc limit 1)concept_id from unnest(p_ids)with ordinality u(id,ord)join maths._user_runtime(p_uid)r on r.question_id=u.id left join maths.question_state st on st.user_id=p_uid and st.question_id=r.question_id),rot as(select s.*,(not p_force_memory_reveal and upper(coalesce(s.answer_mode,''))<>'REVEAL' and s.ckey in('A','B','C','D')and s.last_key=s.ckey)rotate_key,case s.ckey when'A'then'B'when'B'then'C'when'C'then'D'when'D'then'A'else''end swap_key from src s)select coalesce(jsonb_agg(jsonb_build_object('questionId',r.question_id,'chapter',coalesce(r.chapter,''),'topic',coalesce(r.topic,''),'subtopic',coalesce(r.subtopic,''),'majorTopic',coalesce(r.major_topic,''),'prompt',r.prompt,'answer',coalesce(r.answer,''),'explanation',coalesce(r.explanation,''),'memoryCue',coalesce(r.memory_cue,''),'answerMode',case when p_force_memory_reveal or upper(coalesce(r.answer_mode,''))='REVEAL' or r.ckey not in('A','B','C','D')then'REVEAL'else'MCQ'end,'options',case when p_force_memory_reveal or upper(coalesce(r.answer_mode,''))='REVEAL' or r.ckey not in('A','B','C','D')then'[]'::jsonb else jsonb_build_array(jsonb_build_object('key','A','text',case when r.rotate_key and r.ckey='A'then r.omap->>r.swap_key when r.rotate_key and r.swap_key='A'then r.omap->>r.ckey else r.omap->>'A'end),jsonb_build_object('key','B','text',case when r.rotate_key and r.ckey='B'then r.omap->>r.swap_key when r.rotate_key and r.swap_key='B'then r.omap->>r.ckey else r.omap->>'B'end),jsonb_build_object('key','C','text',case when r.rotate_key and r.ckey='C'then r.omap->>r.swap_key when r.rotate_key and r.swap_key='C'then r.omap->>r.ckey else r.omap->>'C'end),jsonb_build_object('key','D','text',case when r.rotate_key and r.ckey='D'then r.omap->>r.swap_key when r.rotate_key and r.swap_key='D'then r.omap->>r.ckey else r.omap->>'D'end))end,'correctOption',case when p_force_memory_reveal or upper(coalesce(r.answer_mode,''))='REVEAL' or r.ckey not in('A','B','C','D')then''when r.rotate_key then r.swap_key else r.ckey end,'variantType',case when p_force_memory_reveal then'CALC_RECALL'else coalesce(nullif(r.variant_types,''),nullif(r.template_group,''),'STATIC')end,'familyId',r.family_id,'conceptId',r.concept_id,'expectedSec',r.expected_sec,'starred',r.starred,'difficult',r.difficult,'mastered',r.mastered,'persistentFamilyWeak',coalesce((select fs.persistent_weak from maths.family_state fs where fs.user_id=p_uid and fs.family_id=r.family_id),false),'inConcept',exists(select 1 from maths.concept_membership c where c.user_id=p_uid and c.question_id=r.question_id and c.active),'diagram',case when r.diagram_json is null then null else jsonb_build_object('type',r.diagram_type,'payload',r.diagram_json)end,'sourceFile',coalesce(r.source_file,''),'sourcePage',coalesce(r.source_page,''))order by r.ord),'[]'::jsonb)from rot r$$;

create or replace function public.maths_get_local_safe_start_v45(p_start_rpc text,p_args jsonb default '{}'::jsonb)returns jsonb language plpgsql security definer set search_path='pg_catalog','public','maths' as $$declare uid uuid:=maths._require_uid();name_ text:=lower(coalesce(p_start_rpc,''));args jsonb:=coalesce(p_args,'{}'::jsonb);ids text[];day_ int:=maths._study_day();count_ int;reason_ text;begin if name_='maths_start_daily'then count_:=greatest(1,coalesce(nullif(maths._setting('daily_chapter_size','25'),'')::int,25));ids:=maths._select_daily_ids_v45(uid,day_,count_,array[]::text[]);return maths._preview_session(uid,ids,'daily','Day '||day_||' · Mixed Revision',jsonb_build_object('planDay',day_,'planChapter','Mixed Revision','dailyVersion','v45-repair'),false);elsif name_='maths_start_repair'then count_:=greatest(1,least(coalesce(nullif(args->>'p_count','')::int,5),20));reason_:=nullif(upper(args->>'p_reason'),'');ids:=maths._repair_candidate_ids(uid,count_,reason_);return maths._preview_session(uid,ids,'repair','Targeted Repair'||case when reason_ is null then''else' · '||reason_ end,args,false);elsif name_='maths_start_mixed'then count_:=greatest(1,least(coalesce(nullif(args->>'p_count','')::int,20),50));ids:=maths._select_daily_ids_v45(uid,day_,count_,array[]::text[]);return maths._preview_session(uid,ids,'mixed_transfer','Mixed Practice · Transfer',args,false);elsif name_='maths_start_sprint'then ids:=maths._sprint_ids(uid,25);return maths._preview_session(uid,ids,'section_sprint','SSC Maths Section Sprint',jsonb_build_object('durationSec',900,'questionCount',25,'marksCorrect',2,'marksWrong',-.5,'selectionCapture',coalesce((args->>'p_diagnostic')::boolean,false),'examMode',true),false);elsif name_='maths_start_calculation' and lower(coalesce(args->>'p_mode','timed'))='timed'then count_:=greatest(40,least(coalesce(nullif(args->>'p_count','')::int,40),80));ids:=maths._calculation_ids(uid,count_,nullif(args->>'p_skill',''));return maths._preview_session(uid,ids,'calculation_speed','10-Min Calculation Drill',jsonb_build_object('mode','timed','skill',nullif(args->>'p_skill',''),'durationSec',600,'calculationTimed',true,'refillBatch',20),false);else return public.maths_get_local_safe_start(p_start_rpc,p_args);end if;end$$;

revoke all on function maths._repair_candidate_ids(uuid,integer,text)from public,anon,authenticated;revoke all on function maths._select_daily_ids_v45(uuid,integer,integer,text[])from public,anon,authenticated;revoke all on function maths._sprint_ids(uuid,integer)from public,anon,authenticated;revoke all on function maths._session_score(uuid,text)from public,anon,authenticated;revoke all on function maths._sprint_stability(uuid)from public,anon,authenticated;revoke all on function maths._calculation_ids(uuid,integer,text)from public,anon,authenticated;
revoke all on function public.maths_get_repair_queue(integer)from public,anon;grant execute on function public.maths_get_repair_queue(integer)to authenticated;revoke all on function public.maths_start_repair(integer,text)from public,anon;grant execute on function public.maths_start_repair(integer,text)to authenticated;revoke all on function public.maths_start_mixed(integer)from public,anon;grant execute on function public.maths_start_mixed(integer)to authenticated;revoke all on function public.maths_start_sprint(boolean)from public,anon;grant execute on function public.maths_start_sprint(boolean)to authenticated;revoke all on function public.maths_get_sprint_analysis(text)from public,anon;grant execute on function public.maths_get_sprint_analysis(text)to authenticated;revoke all on function public.maths_refill_calculation_session(text,integer)from public,anon;grant execute on function public.maths_refill_calculation_session(text,integer)to authenticated;revoke all on function public.maths_get_calculation_summary(text)from public,anon;grant execute on function public.maths_get_calculation_summary(text)to authenticated;revoke all on function public.maths_get_approach_hub(integer)from public,anon;grant execute on function public.maths_get_approach_hub(integer)to authenticated;revoke all on function public.maths_record_approach_recall(text,boolean,numeric)from public,anon;grant execute on function public.maths_record_approach_recall(text,boolean,numeric)to authenticated;revoke all on function public.maths_save_approach_card(text,text,text,text,text,text)from public,anon;grant execute on function public.maths_save_approach_card(text,text,text,text,text,text)to authenticated;revoke all on function public.maths_stage_external_mock(jsonb,text,text)from public,anon;grant execute on function public.maths_stage_external_mock(jsonb,text,text)to authenticated;revoke all on function public.maths_resolve_external_mock_stage(uuid,text,numeric)from public,anon;grant execute on function public.maths_resolve_external_mock_stage(uuid,text,numeric)to authenticated;revoke all on function public.maths_get_readiness()from public,anon;grant execute on function public.maths_get_readiness()to authenticated;revoke all on function public.maths_get_local_safe_start_v45(text,jsonb)from public,anon;grant execute on function public.maths_get_local_safe_start_v45(text,jsonb)to authenticated;
revoke all on function public.maths_start_daily()from public,anon;grant execute on function public.maths_start_daily()to authenticated;revoke all on function public.maths_start_calculation(text,text,text,integer)from public,anon;grant execute on function public.maths_start_calculation(text,text,text,integer)to authenticated;revoke all on function public.maths_get_calculation_hub()from public,anon;grant execute on function public.maths_get_calculation_hub()to authenticated;revoke all on function public.maths_finish_session(text)from public,anon;grant execute on function public.maths_finish_session(text)to authenticated;
